ALTER TABLE public.membership_requests ADD COLUMN vehicle_plan_months integer NOT NULL DEFAULT 1;
CREATE OR REPLACE FUNCTION public.mark_new_vehicle_plan() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.amount=100 THEN NEW.vehicle_plan_months:=3; END IF; RETURN NEW; END $$;
CREATE TRIGGER mark_new_vehicle_plan BEFORE INSERT ON public.membership_requests FOR EACH ROW EXECUTE FUNCTION public.mark_new_vehicle_plan();
CREATE OR REPLACE FUNCTION public.review_membership_evidence(_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.membership_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO r FROM public.membership_requests WHERE id=_id FOR UPDATE; IF r.id IS NULL OR r.status<>'pending' THEN RAISE EXCEPTION 'REVIEW_REQUIRED'; END IF; UPDATE public.membership_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,reviewed_at=now(),reviewed_by=auth.uid() WHERE id=_id; UPDATE public.membership_access SET source=CASE WHEN _approve THEN 'confirmed' ELSE source END,starts_at=CASE WHEN _approve THEN now() ELSE starts_at END,ends_at=CASE WHEN _approve THEN now()+make_interval(months=>r.vehicle_plan_months) ELSE ends_at END,revoked_at=CASE WHEN _approve THEN NULL ELSE now() END,granted_by=auth.uid() WHERE request_id=_id; IF _approve AND r.payer_id=r.user_id THEN PERFORM public.confirm_referral_cash(r.user_id,r.reference,r.amount::bigint*100); END IF; INSERT INTO public.messages(sender_id,receiver_id,body,is_auto) VALUES(auth.uid(),r.user_id,CASE WHEN _approve THEN 'మీరు అమౌంట్ కట్టారని భావిస్తున్నాము. 24 గంటల్లో మీ సబ్స్క్రైబర్ యాక్టివేషన్ అవుతుంది.' ELSE 'మీ చెల్లింపు నిర్ధారణ కాలేదు. అడ్మిన్ తో చాట్ చేయండి.' END,true); END $$;
REVOKE ALL ON FUNCTION public.review_membership_evidence(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.review_membership_evidence(uuid,boolean) TO authenticated;
COMMENT ON COLUMN public.membership_requests.vehicle_plan_months IS 'Historical requests retain one month; new 100-rupee requests have three calendar months after administrator approval.';